#define keyToggle(c)  ( texelFetch(iChannel3,ivec2(c,2),0).x > 0.)

void mainImage( out vec4 O, vec2 u ) {
    O = keyToggle(32) ? textureLod(iChannel2,T(u).xy,0.)
                      : textureLod(iChannel1,T(u).xy,0.);
}

#define W    round( R.y / N )                                       // bands width
#define P(u) floor( (u) / W )                                       // band Id

#define roll( band, axe ) /* +in: S = motion */                     /* --- roll  texture bands */ \
        S[ axe > 0.?1 :0 ] = 0.;                                    /* keep initial direction */  \
        if ( P(u)*S.yx == P(band)*S.yx )                            /* if in target band      */  \
            O = T( mod( u - W*sign(S) , floor(R/W)*W )  );          /* roll                   */

void mainImage( out vec4 O, vec2 u )
{
    O = T(u);                                                       // previous state
    vec4 M = abs(iMouse);
    vec2 A,S;
    if      ( u==vec2(.5) )                                         // --- mouse state
        A = abs ( M.xy - M.zw ),
        O = vec4( M.xy, 0,                                          // .xy = prev mouse location
                  iMouse.w>0. || O.w==0. ? sign(A.x - A.y) : O.w ); // .w  = direction at click 1:horiz -1:vertic 0:none

    else if ( iFrame < 1  )                                         // --- init
         O.xy = u/R;                                                // canonical UV mapping

    else if ( iFrame < 30  ) {                                      // --- scrambling
         vec3 H = fract(cos(iTime* vec3(12.9898, 78.233, -37.94)) * 4e3);
         S = fract(H.zz*2.) - .5;                                   // rand direction & sign
         roll( R*H.xy, H.z-.5 );
    }

    else if ( iFrame%7 < 1 && iMouse.z > 0. && iMouse.w < 0. ) {    // --- mapping roll
        S = M.xy - T(0).xy;                                         // mouse move
        roll( M.zw, T(0).w );
    }
}
